return new Promise((resolve, reject) => {
			// Create a unique symbol for tracking this task
			const taskSymbol = Symbol(`task-${options.id}`);

			// If the signal is already aborted before the task is enqueued,
			// reject immediately without ever entering the queue.
			if (options.signal?.aborted) {
				reject(options.signal.reason);
				return;
			}

			// Set up an abort listener that removes the task from the queue
			// if it is aborted while still queued (waiting on concurrency/rate
			// limits). Once the task starts running, this listener is detached
			// and the inner abort handling takes over.
			const queuedAbortListener = () => {
				const removed = this.#queue.remove(options.id!);
				if (removed !== undefined) {
					reject(options.signal!.reason);
				}
			};

			if (options.signal) {
				options.signal.addEventListener('abort', queuedAbortListener, {once: true});
			}

			this.#queue.enqueue(async () => {
				// Task is now dequeued and about to start running.
				// Detach the queued abort listener - if the signal is aborted
				// during execution, the inner abort handling (eventListener)
				// will reject the operation with signal.reason.
				if (options.signal) {
					options.signal.removeEventListener('abort', queuedAbortListener);
				}

				this.#pending++;

