import { describe, test } from "node:test";
import assert from "node:assert/strict";
import PQueue from "../source/index.js";

describe("p-queue regression", () => {
	test("basic queue", async () => {
		const queue = new PQueue({ concurrency: 2 });
		const results: number[] = [];
		await queue.add(() => { results.push(1); return Promise.resolve(); });
		await queue.add(() => { results.push(2); return Promise.resolve(); });
		await queue.onIdle();
		assert.deepEqual(results, [1, 2]);
	});

	test("concurrency", async () => {
		const queue = new PQueue({ concurrency: 1 });
		let running = 0;
		let max = 0;
		const task = async () => {
			running++;
			max = Math.max(max, running);
			await new Promise(r => setTimeout(r, 10));
			running--;
		};
		await Promise.all([queue.add(task), queue.add(task), queue.add(task)]);
		assert.equal(max, 1);
	});

	test("aborting signal while queued rejects and removes the task from the queue", async () => {
		const queue = new PQueue({ concurrency: 1 });

		// First task holds the only concurrency slot until we let it finish.
		let releaseFirst: () => void = () => {};
		const firstDone = new Promise<void>(resolve => {
			releaseFirst = resolve;
		});
		await queue.add(() => firstDone);

		// Second task should be queued (concurrency limit is 1).
		const controller = new AbortController();
		const secondPromise = queue.add(
			async () => {
				throw new Error("Second task should never run");
			},
			{signal: controller.signal},
		);

		// Sanity-check: it really is queued and not running.
		assert.equal(queue.size, 1, "second task should be queued");
		assert.equal(queue.pending, 1, "first task should be running");

		// Abort the signal while the task is still queued.
		controller.abort(new Error("aborted while queued"));

		// The promise should reject with the abort reason.
		await assert.rejects(secondPromise, /aborted while queued/);

		// The task should be removed from the queue.
		assert.equal(queue.size, 0, "aborted task should be removed from the queue");

		// Release the first task; no further tasks remain.
		releaseFirst();
		await queue.onIdle();
		assert.equal(queue.size, 0);
		assert.equal(queue.pending, 0);
	});

	test("aborting signal before add() rejects immediately and does not enqueue", async () => {
		const queue = new PQueue({ concurrency: 1 });
		const controller = new AbortController();
		controller.abort(new Error("pre-aborted"));

		await assert.rejects(
			queue.add(() => Promise.resolve("never"), {signal: controller.signal}),
			/pre-aborted/,
		);

		assert.equal(queue.size, 0, "pre-aborted task should not be enqueued");
		assert.equal(queue.pending, 0);
	});

	test("aborting a running task still rejects via inner abort handling", async () => {
		const queue = new PQueue({ concurrency: 1 });
		const controller = new AbortController();

		const runningPromise = queue.add(
			async ({signal: _signal}: {signal?: AbortSignal}) => {
				await new Promise<void>((resolve, reject) => {
					const timer = setTimeout(resolve, 1000);
					controller.signal.addEventListener("abort", () => {
						clearTimeout(timer);
						reject(controller.signal.reason);
					}, {once: true});
				});
			},
			{signal: controller.signal},
		);

		// Wait until the task has actually started so it is no longer queued.
		await new Promise(r => setTimeout(r, 10));
		assert.equal(queue.pending, 1);
		assert.equal(queue.size, 0);

		controller.abort(new Error("aborted while running"));

		await assert.rejects(runningPromise, /aborted while running/);
		await queue.onIdle();
	});
});

